u0432\u043e\u0434\u044f\u0442\u0441\u044f \u0438 \u043d\u0435 \u043f\u043e\u0434\u0440\u0430\u0437\u0443\u043c\u0435\u0432\u0430\u044e\u0442\u0441\u044f. \u0412\u0441\u0451 \u043d\u0438\u0436\u0435 \u2014 \u043f\u0440\u043e\u0442\u043e\u043a\u043e\u043b, \u0433\u043e\u0442\u043e\u0432\u044b\u0439 \u043a \u0438\u0441\u043f\u043e\u043b\u043d\u0435\u043d\u0438\u044e \u043f\u0440\u0438 \u043f\u0440\u0435\u0434\u043e\u0441\u0442\u0430\u0432\u043b\u0435\u043d\u0438\u0438 \u0432\u043d\u0435\u0448\u043d\u0438\u0445 \u0440\u0435\u0441\u0443\u0440\u0441\u043e\u0432 (\u0441\u043c. \u0440\u0430\u0437\u0434\u0435\u043b v).\n\n---\n\n## (i) \u0426\u0435\u043b\u044c \u0438 \u0432\u043e\u043f\u0440\u043e\u0441\n\n**\u0412\u043e\u043f\u0440\u043e\u0441 (\u0434\u043e\u0441\u043b\u043e\u0432\u043d\u043e):** \u043f\u0440\u0435\u0432\u044b\u0448\u0430\u044e\u0442 \u043b\u0438 \u043e\u043f\u0442\u0438\u043c\u0438\u0437\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0435 \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u0438, \u043d\u0430\u0439\u0434\u0435\u043d\u043d\u044b\u0435 OPRO, \u0431\u0430\u0437\u043e\u0432\u044b\u0435 \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u0438 (\u00abLet's think step by step.\u00bb \u0438 \u043f\u0443\u0441\u0442\u043e\u0439 \u043f\u0440\u043e\u043c\u043f\u0442) \u043d\u0430 \u0437\u0430\u0434\u0430\u0447\u0430\u0445 BBH?\n\n**\u0424\u043e\u0440\u043c\u0430\u043b\u0438\u0437\u0443\u0435\u043c\u044b\u0439 \u043e\u0446\u0435\u043d\u043e\u0447\u043d\u044b\u0439 \u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440 (estimand):** \u0440\u0430\u0437\u043d\u043e\u0441\u0442\u044c \u0441\u0440\u0435\u0434\u043d\u0438\u0445 \u043f\u043e 23 \u0437\u0430\u0434\u0430\u0447\u0430\u043c Big-Bench Hard \u043f\u0435\u0440-\u0437\u0430\u0434\u0430\u0447\u043d\u043e\u0439 accuracy (exact match \u043f\u043e \u043d\u043e\u0440\u043c\u0430\u043b\u0438\u0437\u043e\u0432\u0430\u043d\u043d\u043e\u043c\u0443 \u043e\u0442\u0432\u0435\u0442\u0443) \u043c\u0435\u0436\u0434\u0443 \u0443\u0441\u043b\u043e\u0432\u0438\u0435\u043c \u0441 \u043f\u0435\u0440-\u0437\u0430\u0434\u0430\u0447\u043d\u044b\u043c\u0438 \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u044f\u043c\u0438 OPRO \u0438 \u043a\u0430\u0436\u0434\u043e\u0439 \u0438\u0437 \u0434\u0432\u0443\u0445 \u0431\u0430\u0437\u043e\u0432\u044b\u0445 \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u0439, \u043f\u0440\u0438 \u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u043e\u0439 scorer-\u043c\u043e\u0434\u0435\u043b\u0438 \u0438 \u0438\u0434\u0435\u043d\u0442\u0438\u0447\u043d\u044b\u0445 \u0432\u043e \u0432\u0441\u0435\u0445 \u043e\u0442\u043d\u043e\u0448\u0435\u043d\u0438\u044f\u0445, \u043a\u0440\u043e\u043c\u0435 \u0441\u0430\u043c\u043e\u0439 \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u0438, \u043f\u0440\u043e\u043c\u043f\u0442\u0430\u0445.\n\n**\u0424\u043e\u0440\u043c\u0443\u043b\u0438\u0440\u0443\u044e\u0442\u0441\u044f \u0434\u0432\u0430 \u043f\u0430\u0440\u043d\u044b\u0445 \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u044f:**\n- H1: accuracy(OPRO-\u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u044f) vs accuracy(\u00abLet's think step by step.\u00bb);\n- H2: accuracy(OPRO-\u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u044f) vs accuracy(\u043f\u0443\u0441\u0442\u043e\u0439 \u043f\u0440\u043e\u043c\u043f\u0442).\n\n**\u041f\u0440\u0435-\u0440\u0435\u0433\u0438\u0441\u0442\u0440\u0430\u0446\u0438\u044f:** \u043a\u0440\u0438\u0442\u0435\u0440\u0438\u0439 \u00aboutperform\u00bb (\u0440\u0430\u0437\u0434\u0435\u043b iv) \u0438 \u0441\u043e\u0441\u0442\u0430\u0432 \u0443\u0441\u043b\u043e\u0432\u0438\u0439 \u0444\u0438\u043a\u0441\u0438\u0440\u0443\u044e\u0442\u0441\u044f \u0414\u041e \u043f\u0440\u043e\u0441\u043c\u043e\u0442\u0440\u0430 \u0442\u0435\u0441\u0442\u043e\u0432\u044b\u0445 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u043e\u0432. \u041d\u0438\u043a\u0430\u043a\u0438\u0435 \u0442\u0435\u0441\u0442\u043e\u0432\u044b\u0435 \u043c\u0435\u0442\u043a\u0438 \u043d\u0435 \u0443\u0447\u0430\u0441\u0442\u0432\u0443\u044e\u0442 \u0432 \u043d\u0430\u0441\u0442\u0440\u043e\u0439\u043a\u0435 \u043f\u0430\u0439\u043f\u043b\u0430\u0439\u043d\u0430 (\u0442\u043e\u043b\u044c\u043a\u043e train/validation).\n\n---\n\n## (ii) \u0421\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0435 \u0438 \u0443\u0441\u043b\u043e\u0432\u0438\u044f\n\n### Scorer-\u043c\u043e\u0434\u0435\u043b\u044c\n- \u041e\u0414\u041d\u0410 \u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u0430\u044f \u043c\u043e\u0434\u0435\u043b\u044c \u0434\u043b\u044f \u0432\u0441\u0435\u0445 \u0443\u0441\u043b\u043e\u0432\u0438\u0439, \u0441 \u0437\u0430\u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u043c\u0438 \u0438\u043c\u0435\u043d\u0435\u043c/\u0432\u0435\u0440\u0441\u0438\u0435\u0439 \u0438 \u0434\u0435\u043a\u043e\u0434\u0438\u043d\u0433\u043e\u043c. \u041e\u0431\u043e\u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0435: `M = <\u0438\u043c\u044f/\u0432\u0435\u0440\u0441\u0438\u044f>` \u2014 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0435 \u0432\u044b\u0431\u0438\u0440\u0430\u0435\u0442\u0441\u044f \u0432\u043d\u0435\u0448\u043d\u0435 (\u0441\u043c. v/vi). \u041f\u0440\u0435\u0434\u043f\u043e\u0447\u0442\u0435\u043d\u0438\u0435: \u0441\u043e\u0432\u0440\u0435\u043c\u0435\u043d\u043d\u0430\u044f \u043c\u043e\u0434\u0435\u043b\u044c \u0441 \u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u043e\u0439 \u0432\u0435\u0440\u0441\u0438\u0435\u0439 (\u0432 \u0441\u0442\u0430\u0442\u044c\u0435 OPRO scorer \u2014 PaLM 2-L; \u043f\u0440\u0438 \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u043d\u0438\u0438 \u0434\u0440\u0443\u0433\u043e\u0439 \u043c\u043e\u0434\u0435\u043b\u0438 \u0444\u0438\u043a\u0441\u0438\u0440\u0443\u0435\u0442\u0441\u044f, \u0447\u0442\u043e \u043c\u044b \u043f\u0440\u043e\u0432\u0435\u0440\u044f\u0435\u043c \u041f\u0415\u0420\u0415\u041d\u041e\u0421 \u043e\u043f\u0443\u0431\u043b\u0438\u043a\u043e\u0432\u0430\u043d\u043d\u044b\u0445 \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u0439, \u0430 \u043d\u0435 \u0438\u0445 \u0432\u043d\u0443\u0442\u0440\u0438\u043c\u043e\u0434\u0435\u043b\u044c\u043d\u0443\u044e \u043e\u043f\u0442\u0438\u043c\u0438\u0437\u0430\u0446\u0438\u044e).\n\n### \u0414\u0430\u043d\u043d\u044b\u0435\n- BBH (Big-Bench Hard, Suzgun et al. 2022): \u0432\u0441\u0435 23 \u043a\u0430\u043d\u043e\u043d\u0438\u0447\u0435\u0441\u043a\u0438\u0435 \u0437\u0430\u0434\u0430\u0447\u0438.\n- \u0421\u043f\u043b\u0438\u0442: \u043e\u0444\u0438\u0446\u0438\u0430\u043b\u044c\u043d\u044b\u0439 **test**-\u0441\u043f\u043b\u0438\u0442 \u0432\u044b\u0431\u0440\u0430\u043d\u043d\u043e\u0433\u043e \u0438\u0441\u0442\u043e\u0447\u043d\u0438\u043a\u0430 \u0434\u0430\u043d\u043d\u044b\u0445; \u0432\u0441\u0435 \u043f\u0440\u0438\u043c\u0435\u0440\u044b \u0437\u0430\u0434\u0430\u0447\u0438 (~250 \u043d\u0430 \u0437\u0430\u0434\u0430\u0447\u0443; \u0442\u043e\u0447\u043d\u044b\u0435 \u043f\u0435\u0440-\u0437\u0430\u0434\u0430\u0447\u043d\u044b\u0435 \u0447\u0438\u0441\u043b\u0430 \u0444\u0438\u043a\u0441\u0438\u0440\u0443\u044e\u0442\u0441\u044f \u043f\u043e \u0434\u0430\u043d\u043d\u044b\u043c \u0432\u044b\u0431\u0440\u0430\u043d\u043d\u043e\u0433\u043e \u0438\u0441\u0442\u043e\u0447\u043d\u0438\u043a\u0430 \u0438 \u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442\u0438\u0440\u0443\u044e\u0442\u0441\u044f \u0432 \u043e\u0442\u0447\u0451\u0442\u0435; \u0437\u0430\u0434\u0430\u0447\u0438 \u0441 \u043c\u0435\u043d\u044c\u0448\u0438\u043c \u0447\u0438\u0441\u043b\u043e\u043c \u2014 \u0431\u0435\u0440\u0443\u0442\u0441\u044f \u0446\u0435\u043b\u0438\u043a\u043e\u043c).\n- \u0418\u0441\u0442\u043e\u0447\u043d\u0438\u043a \u0434\u0430\u043d\u043d\u044b\u0445 \u0444\u0438\u043a\u0441\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u0434\u043e \u043f\u0440\u043e\u0433\u043e\u043d\u0430 (\u043d\u0430\u043f\u0440\u0438\u043c\u0435\u0440, \u043e\u0444\u0438\u0446\u0438\u0430\u043b\u044c\u043d\u044b\u0439 \u043d\u0430\u0431\u043e\u0440 BBH \u0438\u0437 \u0440\u0435\u043f\u043e\u0437\u0438\u0442\u043e\u0440\u0438\u044f BIG-bench \u043b\u0438\u0431\u043e \u043a\u0430\u043d\u043e\u043d\u0438\u0447\u0435\u0441\u043a\u043e\u0435 \u0437\u0435\u0440\u043a\u0430\u043b\u043e \u043d\u0430 HuggingFace); \u0432\u0435\u0440\u0441\u0438\u044f/\u043a\u043e\u043c\u043c\u0438\u0442 \u0438\u0441\u0442\u043e\u0447\u043d\u0438\u043a\u0430 \u0438 \u043f\u0435\u0440-\u0437\u0430\u0434\u0430\u0447\u043d\u044b\u0435 \u043c\u0435\u0442\u0440\u0438\u043a\u0438 \u043a\u043e\u043b\u0438\u0447\u0435\u0441\u0442\u0432\u0430 \u043f\u0440\u0438\u043c\u0435\u0440\u043e\u0432 \u0432\u043a\u043b\u044e\u0447\u0430\u044e\u0442\u0441\u044f \u0432 \u043e\u0442\u0447\u0451\u0442.\n- Few-shot: \u0444\u0438\u043a\u0441\u0438\u0440\u0443\u044e\u0442\u0441\u044f \u0441\u0442\u0430\u043d\u0434\u0430\u0440\u0442\u043d\u044b\u0435 \u0434\u043b\u044f BBH \u044d\u043a\u0437\u044d\u043c\u043f\u043b\u044f\u0440\u044b (\u0438\u0437 train-\u0447\u0430\u0441\u0442\u0438 \u0442\u043e\u0433\u043e \u0436\u0435 \u0438\u0441\u0442\u043e\u0447\u043d\u0438\u043a\u0430) \u2014 \u041e\u0414\u0418\u041d\u0410\u041a\u041e\u0412\u042b\u0415 \u043f\u0440\u0438\u043c\u0435\u0440\u044b \u0438 \u041e\u0414\u0418\u041d\u0410\u041a\u041e\u0412\u042b\u0419 \u043f\u043e\u0440\u044f\u0434\u043e\u043a \u0432\u043e \u0432\u0441\u0435\u0445 \u0443\u0441\u043b\u043e\u0432\u0438\u044f\u0445.\n\n### \u0423\u0441\u043b\u043e\u0432\u0438\u044f (\u0432\u0430\u0440\u044c\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u0422\u041e\u041b\u042c\u041a\u041e \u0442\u0435\u043a\u0441\u0442 \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u0438)\n- **A (\u0433\u043e\u043b\u043e\u0432\u043d\u043e\u0435 \u0443\u0441\u043b\u043e\u0432\u0438\u0435, OPRO):** \u0441\u0442\u0440\u043e\u043a\u0430 \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u0438, \u043e\u043f\u0442\u0438\u043c\u0438\u0437\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u043e\u0439 OPRO \u0434\u043b\u044f \u0434\u0430\u043d\u043d\u043e\u0439 \u0437\u0430\u0434\u0430\u0447\u0438 t, \u043e\u043f\u0443\u0431\u043b\u0438\u043a\u043e\u0432\u0430\u043d\u043d\u0430\u044f \u0432 \u0441\u0442\u0430\u0442\u044c\u0435 OPRO (\u0442\u0435\u043a\u0441\u0442 \u0438\u0437 \u043f\u0440\u0438\u043b\u043e\u0436\u0435\u043d\u0438\u044f) \u2192 \u043f\u0443\u0441\u0442\u0430\u044f \u0441\u0442\u0440\u043e\u043a\u0430 \u2192 \u044d\u043a\u0437\u044d\u043c\u043f\u043b\u044f\u0440\u044b \u0437\u0430\u0434\u0430\u0447\u0438 t \u2192 \u0442\u0435\u0441\u0442\u043e\u0432\u044b\u0439 \u0432\u043e\u043f\u0440\u043e\u0441. \u0414\u043b\u044f \u043a\u0430\u0436\u0434\u043e\u0439 \u0438\u0437 23 \u0437\u0430\u0434\u0430\u0447 \u2014 \u0441\u0432\u043e\u044f \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u044f.\n- **A_meta (\u0434\u043e\u043f\u043e\u043b\u043d\u0438\u0442\u0435\u043b\u044c\u043d\u043e\u0435):** \u0433\u043b\u043e\u0431\u0430\u043b\u044c\u043d\u0430\u044f \u043c\u0435\u0442\u0430-\u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u044f OPRO (\u043a\u0440\u043e\u0441\u0441-\u0437\u0430\u0434\u0430\u0447\u043d\u0430\u044f), \u0435\u0441\u043b\u0438 \u0435\u0451 \u0442\u043e\u0447\u043d\u0430\u044f \u0441\u0442\u0440\u043e\u043a\u0430 \u0432\u0435\u0440\u0438\u0444\u0438\u0446\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u043f\u043e \u0438\u0441\u0442\u043e\u0447\u043d\u0438\u043a\u0443. \u0412\u043a\u043b\u044e\u0447\u0430\u0435\u0442\u0441\u044f \u0442\u043e\u043b\u044c\u043a\u043e \u043f\u0440\u0438 \u0443\u0441\u043f\u0435\u0448\u043d\u043e\u0439 \u0432\u0435\u0440\u0438\u0444\u0438\u043a\u0430\u0446\u0438\u0438 \u0441\u0442\u0440\u043e\u043a\u0438; \u0432 \u043f\u0440\u043e\u0442\u0438\u0432\u043d\u043e\u043c \u0441\u043b\u0443\u0447\u0430\u0435 \u0444\u0438\u043a\u0441\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u043a\u0430\u043a \u0438\u0441\u043a\u043b\u044e\u0447\u0451\u043d\u043d\u043e\u0435.\n- **C1 (\u0431\u0430\u0437\u0438\u043b\u043a\u0430 1):** \u00abLet's think step by step.\u00bb \u2192 \u0442\u0430 \u0436\u0435 \u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u0430 (\u044d\u043a\u0437\u044d\u043c\u043f\u043b\u044f\u0440\u044b \u2192 \u0442\u0435\u0441\u0442). \u042d\u0442\u043e zero-shot-CoT-\u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u044f (Kojima et al. 2022), \u043f\u043e\u043c\u0435\u0449\u0451\u043d\u043d\u0430\u044f \u0432 \u0442\u0443 \u0436\u0435 few-shot-\u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u0443, \u0447\u0442\u043e \u0438 \u0443\u0441\u043b\u043e\u0432\u0438\u0435 A.\n- **C2 (\u0431\u0430\u0437\u0438\u043b\u043a\u0430 2, \u043f\u0443\u0441\u0442\u043e\u0439 \u043f\u0440\u043e\u043c\u043f\u0442):** \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u044f \u043e\u0442\u0441\u0443\u0442\u0441\u0442\u0432\u0443\u0435\u0442; \u0442\u043e\u043b\u044c\u043a\u043e \u044d\u043a\u0437\u044d\u043c\u043f\u043b\u044f\u0440\u044b \u2192 \u0442\u0435\u0441\u0442\u043e\u0432\u044b\u0439 \u0432\u043e\u043f\u0440\u043e\u0441.\n- **D (\u0440\u0435\u0444\u0435\u0440\u0435\u043d\u0441, \u041d\u0415 \u043f\u0435\u0440\u0432\u0438\u0447\u043d\u0430\u044f \u0431\u0430\u0437\u0438\u043b\u043a\u0430):** \u0447\u0435\u043b\u043e\u0432\u0435\u0447\u0435\u0441\u043a\u0430\u044f CoT-\u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u044f, \u0432\u0448\u0438\u0442\u0430\u044f \u0432 \u043a\u0430\u0436\u0434\u0443\u044e BBH-\u0437\u0430\u0434\u0430\u0447\u0443 + \u0442\u0435 \u0436\u0435 \u044d\u043a\u0437\u044d\u043c\u043f\u043b\u044f\u0440\u044b. \u0421\u043b\u0443\u0436\u0438\u0442 \u044f\u043a\u043e\u0440\u0435\u043c \u043e\u0442\u043d\u043e\u0441\u0438\u0442\u0435\u043b\u044c\u043d\u043e \u043b\u0438\u0442\u0435\u0440\u0430\u0442\u0443\u0440\u044b (\u0443 OPRO \u0432 \u0441\u0442\u0430\u0442\u044c\u0435 \u0432\u043d\u0443\u0442\u0440\u0435\u043d\u043d\u0438\u0439 baseline \u2014 \u0447\u0435\u043b\u043e\u0432\u0435\u0447\u0435\u0441\u043a\u0438\u0435 \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u0438 BBH), \u043d\u043e \u043d\u0435 \u0443\u0447\u0430\u0441\u0442\u0432\u0443\u0435\u0442 \u0432 \u043a\u0440\u0438\u0442\u0435\u0440\u0438\u0438 \u0440\u0435\u0448\u0435\u043d\u0438\u044f.\n\n**\u0420\u0430\u0441\u043a\u043b\u0430\u0434\u043a\u0430 \u043f\u0440\u043e\u043c\u043f\u0442\u0430** \u0432\u043e \u0432\u0441\u0435\u0445 \u0443\u0441\u043b\u043e\u0432\u0438\u044f\u0445: `[\u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u044f | \u043e\u0442\u0441\u0443\u0442\u0441\u0442\u0432\u0443\u0435\u0442]` \u2192 \u043f\u0443\u0441\u0442\u0430\u044f \u0441\u0442\u0440\u043e\u043a\u0430 \u2192 \u044d\u043a\u0437\u044d\u043c\u043f\u043b\u044f\u0440\u044b (\u0432\u043e\u043f\u0440\u043e\u0441+\u043e\u0442\u0432\u0435\u0442 \u0432 \u0444\u043e\u0440\u043c\u0430\u0442\u0435 \u0437\u0430\u0434\u0430\u0447\u0438) \u2192 `\\nQ: <\u0442\u0435\u0441\u0442\u043e\u0432\u044b\u0439 \u0432\u043e\u043f\u0440\u043e\u0441>` \u2192 (\u0434\u043b\u044f CoT-\u0443\u0441\u043b\u043e\u0432\u0438\u0439) \u043f\u043e\u0431\u0443\u0436\u0434\u0435\u043d\u0438\u0435 \u043a \u0440\u0430\u0441\u0441\u0443\u0436\u0434\u0435\u043d\u0438\u044e. \u0424\u043e\u0440\u043c\u0430\u0442 \u0438\u0434\u0435\u043d\u0442\u0438\u0447\u0435\u043d \u043c\u0435\u0436\u0434\u0443 \u0443\u0441\u043b\u043e\u0432\u0438\u044f\u043c\u0438 \u0441 \u0442\u043e\u0447\u043d\u043e\u0441\u0442\u044c\u044e \u0434\u043e \u0441\u043e\u0434\u0435\u0440\u0436\u0438\u043c\u043e\u0433\u043e \u0441\u0442\u0440\u043e\u043a\u0438 \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u0438. \u042d\u043a\u0437\u044d\u043c\u043f\u043b\u044f\u0440\u044b \u0438 \u0442\u0435\u0441\u0442\u043e\u0432\u044b\u0435 \u043f\u0440\u0438\u043c\u0435\u0440\u044b \u2014 \u043f\u0430\u0440\u043d\u044b\u0439 \u0434\u0438\u0437\u0430\u0439\u043d: \u043e\u0434\u0438\u043d \u0438 \u0442\u043e\u0442 \u0436\u0435 \u043f\u0440\u0438\u043c\u0435\u0440 \u0432\u043e \u0432\u0441\u0435\u0445 \u0443\u0441\u043b\u043e\u0432\u0438\u044f\u0445.\n\n**\u0418\u0437\u0432\u043b\u0435\u0447\u0435\u043d\u0438\u0435 \u043e\u0442\u0432\u0435\u0442\u0430:** \u0435\u0434\u0438\u043d\u044b\u0439 \u0434\u0435\u0442\u0435\u0440\u043c\u0438\u043d\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0439 \u043f\u0430\u0439\u043f\u043b\u0430\u0439\u043d \u0434\u043b\u044f \u0432\u0441\u0435\u0445 \u0443\u0441\u043b\u043e\u0432\u0438\u0439: \u043f\u043e\u0438\u0441\u043a \u043f\u043e \u0448\u0430\u0431\u043b\u043e\u043d\u0430\u043c \u00abanswer is \u2026\u00bb / \u00abthe answer is \u2026\u00bb / \u043f\u043e\u0441\u043b\u0435\u0434\u043d\u044f\u044f \u0441\u0442\u0440\u043e\u043a\u0430; \u043d\u043e\u0440\u043c\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u044f BBH-\u0441\u0442\u0438\u043b\u044f (lowercase, strip, \u0443\u0434\u0430\u043b\u0435\u043d\u0438\u0435 \u043f\u0440\u043e\u0431\u0435\u043b\u043e\u0432; \u0434\u043b\u044f MCQ \u2014 \u0431\u0443\u043a\u0432\u0430 \u0432\u0430\u0440\u0438\u0430\u043d\u0442\u0430; \u0434\u043b\u044f \u0447\u0438\u0441\u043b\u043e\u0432\u044b\u0445 \u2014 \u0441\u0442\u0440\u043e\u043a\u0430 \u0447\u0438\u0441\u043b\u0430). \u0421\u0431\u043e\u0439 \u0438\u0437\u0432\u043b\u0435\u0447\u0435\u043d\u0438\u044f = \u00ab\u043d\u0435\u0432\u0435\u0440\u043d\u043e\u00bb + \u043e\u0442\u0434\u0435\u043b\u044c\u043d\u044b\u0439 \u0430\u0431\u0438\u043b\u044f\u0446\u0438\u043e\u043d\u043d\u044b\u0439 \u043f\u043e\u0434\u0441\u0447\u0451\u0442 \u0434\u043e\u043b\u0438 \u0441\u0431\u043e\u0435\u0432 \u043f\u043e \u0443\u0441\u043b\u043e\u0432\u0438\u044e.\n\n### (\u041e\u0442\u0434\u0435\u043b\u044c\u043d\u044b\u0439 \u0440\u0430\u0437\u0434\u0435\u043b) \u0410\u0440\u043c \u043f\u0435\u0440\u0435-\u043e\u043f\u0442\u0438\u043c\u0438\u0437\u0430\u0446\u0438\u0438 (\u043e\u043f\u0446\u0438\u043e\u043d\u0430\u043b\u044c\u043d\u044b\u0439, arm \u043d\u0430\u0434\u0451\u0436\u043d\u043e\u0441\u0442\u0438)\n- \u0412\u044b\u043f\u043e\u043b\u043d\u044f\u0435\u0442\u0441\u044f \u0422\u041e\u041b\u042c\u041a\u041e \u043f\u0440\u0438 \u043d\u0430\u043b\u0438\u0447\u0438\u0438 \u0432\u043d\u0435\u0448\u043d\u0435\u0439 \u0438\u043d\u0444\u0440\u0430\u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u044b/\u0431\u044e\u0434\u0436\u0435\u0442\u0430; \u0432 \u043f\u0440\u043e\u0442\u0438\u0432\u043d\u043e\u043c \u0441\u043b\u0443\u0447\u0430\u0435 \u0444\u0438\u043a\u0441\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u043a\u0430\u043a \u0438\u0441\u043a\u043b\u044e\u0447\u0451\u043d\u043d\u044b\u0439 (\u0437\u0430\u043f\u0438\u0441\u044c \u0432 \u043e\u0442\u0447\u0451\u0442\u0435).\n- \u041f\u0440\u043e\u0446\u0435\u0434\u0443\u0440\u0430: \u043c\u0435\u0442\u0430\u044d\u0432\u0440\u0438\u0441\u0442\u0438\u043a\u0430 OPRO (\u043c\u043e\u0434\u0435\u043b\u044c-\u043e\u043f\u0442\u0438\u043c\u0438\u0437\u0430\u0442\u043e\u0440 \u0433\u0435\u043d\u0435\u0440\u0438\u0440\u0443\u0435\u0442 \u043a\u0430\u043d\u0434\u0438\u0434\u0430\u0442\u043e\u0432-\u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u0439; scorer \u043e\u0446\u0435\u043d\u0438\u0432\u0430\u0435\u0442 \u0438\u0445 \u043d\u0430 \u043d\u0435\u0431\u043e\u043b\u044c\u0448\u043e\u043c \u0432\u0430\u043b\u0438\u0434\u0430\u0446\u0438\u043e\u043d\u043d\u043e\u043c \u043d\u0430\u0431\u043e\u0440\u0435; \u0442\u043e\u043f-\u043a\u0430\u043d\u0434\u0438\u0434\u0430\u0442 \u2014 \u043d\u0430 \u0441\u043b\u0435\u0434\u0443\u044e\u0449\u0435\u043c \u0448\u0430\u0433\u0435). \u041e\u043f\u0442\u0438\u043c\u0438\u0437\u0430\u0446\u0438\u044f \u2014 \u043d\u0430 **validation**-\u0441\u043f\u043b\u0438\u0442\u0435, \u0441\u0442\u0440\u043e\u0433\u043e \u043e\u0442\u0434\u0435\u043b\u044c\u043d\u043e \u043e\u0442 test.\n- \u0420\u0430\u0441\u043a\u0440\u044b\u0442\u044b\u0439 \u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0439 \u0431\u044e\u0434\u0436\u0435\u0442 (\u0440\u0435\u043a\u043e\u043c\u0435\u043d\u0434\u0443\u0435\u043c\u044b\u0439, \u043c\u043e\u0436\u0435\u0442 \u0431\u044b\u0442\u044c \u0441\u043d\u0438\u0436\u0435\u043d \u043f\u0440\u0438 \u0434\u0435\u0444\u0438\u0446\u0438\u0442\u0435): `steps \u00d7 candidates \u00d7 val_examples` \u0441 \u043f\u0440\u0438\u043c\u0435\u0440\u043e\u043c `20 \u00d7 100 \u00d7 8`.\n- \u0420\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442 \u0430\u0440\u043c\u0430 \u043f\u0443\u0431\u043b\u0438\u043a\u0443\u0435\u0442\u0441\u044f \u0431\u043e\u043a\u043e\u0432\u044b\u043c \u0447\u0438\u0441\u043b\u043e\u043c; \u0433\u043e\u043b\u043e\u0432\u043d\u044b\u043c \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u043e\u043c \u043e\u0441\u0442\u0430\u0451\u0442\u0441\u044f \u0443\u0441\u043b\u043e\u0432\u0438\u0435 A \u0441 \u043e\u043f\u0443\u0431\u043b\u0438\u043a\u043e\u0432\u0430\u043d\u043d\u044b\u043c\u0438 \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u044f\u043c\u0438.\n\n---\n\n## (iii) \u041a\u043e\u043d\u0442\u0440\u043e\u043b\u0438\n\n1. **\u0414\u0435\u043a\u043e\u0434\u0438\u043d\u0433:** temperature = 0 (greedy) \u0434\u043b\u044f \u0432\u0441\u0435\u0445 \u0443\u0441\u043b\u043e\u0432\u0438\u0439; \u0435\u0441\u043b\u0438 \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u0443\u0435\u0442\u0441\u044f \u0441\u044d\u043c\u043f\u043b\u0438\u043d\u0433 (\u043d\u0430\u043f\u0440\u0438\u043c\u0435\u0440, \u0434\u043b\u044f \u043e\u0446\u0435\u043d\u043a\u0438 \u0432\u0430\u0440\u0438\u0430\u0446\u0438\u0438) \u2014 \u043e\u0434\u0438\u043d \u0438 \u0442\u043e\u0442 \u0436\u0435 seed \u043d\u0430 \u043f\u0440\u0438\u043c\u0435\u0440 \u0432\u043e \u0432\u0441\u0435\u0445 \u0443\u0441\u043b\u043e\u0432\u0438\u044f\u0445, \u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0435 `max_new_tokens` (\u043d\u0430\u043f\u0440., 512) \u0438 \u043e\u0434\u0438\u043d\u0430\u043a\u043e\u0432\u044b\u0435 stop-\u0442\u043e\u043a\u0435\u043d\u044b.\n2. **\u041f\u043e\u0440\u044f\u0434\u043e\u043a:** \u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0435 \u044d\u043a\u0437\u044d\u043c\u043f\u043b\u044f\u0440\u044b \u0438 \u0438\u0445 \u043f\u043e\u0440\u044f\u0434\u043e\u043a; \u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0439 \u043f\u043e\u0440\u044f\u0434\u043e\u043a \u0442\u0435\u0441\u0442\u043e\u0432\u044b\u0445 \u043f\u0440\u0438\u043c\u0435\u0440\u043e\u0432; \u043e\u0434\u0438\u043d\u0430\u043a\u043e\u0432\u044b\u0435 \u0432\u043e \u0432\u0441\u0435\u0445 \u0443\u0441\u043b\u043e\u0432\u0438\u044f\u0445.\n3. **\u0415\u0434\u0438\u043d\u044b\u0439 \u043a\u043e\u0434 \u0441\u043a\u043e\u0440\u0438\u043d\u0433\u0430:** \u043e\u0434\u043d\u0430 \u0444\u0443\u043d\u043a\u0446\u0438\u044f \u043d\u043e\u0440\u043c\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u0438+\u0438\u0437\u0432\u043b\u0435\u0447\u0435\u043d\u0438\u044f+\u0442\u043e\u0447\u043d\u043e\u0433\u043e \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u044f \u0434\u043b\u044f \u0432\u0441\u0435\u0445 \u0443\u0441\u043b\u043e\u0432\u0438\u0439 \u0438 \u0437\u0430\u0434\u0430\u0447; \u0435\u0434\u0438\u043d\u0430\u044f \u0432\u0435\u0440\u0441\u0438\u044f scorer-\u043c\u043e\u0434\u0435\u043b\u0438; \u043d\u0438\u043a\u0430\u043a\u0438\u0445 \u0438\u0437\u043c\u0435\u043d\u0435\u043d\u0438\u0439 \u043f\u0430\u0439\u043f\u043b\u0430\u0439\u043d\u0430 \u043c\u0435\u0436\u0434\u0443 \u0443\u0441\u043b\u043e\u0432\u0438\u044f\u043c\u0438.\n4. **\u0420\u0430\u0437\u0431\u0440\u043e\u0441:** 95% \u0431\u0443\u0442\u0441\u0442\u0440\u0430\u043f-CI \u043f\u043e \u0437\u0430\u0434\u0430\u0447\u0430\u043c (\u0440\u0430\u0437\u0434\u0435\u043b iv); \u043f\u0440\u0438 \u0434\u043e\u0441\u0442\u0443\u043f\u043d\u043e\u0441\u0442\u0438 \u0431\u044e\u0434\u0436\u0435\u0442\u0430 \u2014 \u043f\u043e\u0432\u0442\u043e\u0440 \u043f\u043e\u043b\u043d\u043e\u0433\u043e \u043f\u0440\u043e\u0433\u043e\u043d\u0430 3\u00d7 (3 seed) \u0441 \u043e\u0442\u0447\u0451\u0442\u043e\u043c mean\u00b1sd \u043f\u043e \u043f\u0440\u043e\u0433\u043e\u043d\u0430\u043c. \u0415\u0441\u043b\u0438 \u043f\u043e\u0432\u0442\u043e\u0440\u043d\u044b\u0435 \u043f\u0440\u043e\u0433\u043e\u043d\u044b \u043d\u0435\u0432\u043e\u0437\u043c\u043e\u0436\u043d\u044b, CI \u043f\u043e \u0437\u0430\u0434\u0430\u0447\u0430\u043c \u2014 \u0435\u0434\u0438\u043d\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0439 \u043e\u0442\u0447\u0451\u0442 \u043e \u0440\u0430\u0437\u0431\u0440\u043e\u0441\u0435 (\u0444\u0438\u043a\u0441\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u0432 \u043e\u0442\u0447\u0451\u0442\u0435).\n5. **\u0411\u044e\u0434\u0436\u0435\u0442:** \u0432 \u043e\u0442\u0447\u0451\u0442\u0435 \u0440\u0430\u0441\u043a\u0440\u044b\u0432\u0430\u044e\u0442\u0441\u044f \u0447\u0438\u0441\u043b\u043e LLM-\u0432\u044b\u0437\u043e\u0432\u043e\u0432 \u0438 \u0442\u043e\u043a\u0435\u043d\u043e\u0432 (\u0432\u0445\u043e\u0434/\u0432\u044b\u0445\u043e\u0434) \u043f\u043e \u043a\u0430\u0436\u0434\u043e\u043c\u0443 \u0443\u0441\u043b\u043e\u0432\u0438\u044e \u0438 \u0438\u0441\u0442\u043e\u0447\u043d\u0438\u043a\u0443.\n6. **\u0417\u0430\u0449\u0438\u0442\u0430 \u043e\u0442 \u0443\u0442\u0435\u0447\u043a\u0438:** test-\u0441\u043f\u043b\u0438\u0442 \u0443\u0447\u0430\u0441\u0442\u0432\u0443\u0435\u0442 \u0442\u043e\u043b\u044c\u043a\u043e \u0432 \u0444\u0438\u043d\u0430\u043b\u044c\u043d\u043e\u043c \u0441\u043a\u043e\u0440\u0438\u043d\u0433\u0435; \u0432\u0441\u044f \u043d\u0430\u0441\u0442\u0440\u043e\u0439\u043a\u0430 (\u043e\u0442\u043b\u0430\u0434\u043a\u0430 \u043f\u0430\u0439\u043f\u043b\u0430\u0439\u043d\u0430, \u0432\u0430\u043b\u0438\u0434\u0430\u0446\u0438\u044f \u0438\u0437\u0432\u043b\u0435\u0447\u0435\u043d\u0438\u044f) \u2014 \u043d\u0430 train/validation; \u0430\u0440\u043c \u043f\u0435\u0440\u0435-\u043e\u043f\u0442\u0438\u043c\u0438\u0437\u0430\u0446\u0438\u0438 \u2014 \u0442\u043e\u043b\u044c\u043a\u043e \u043d\u0430 validation. \u0414\u043e\u043f\u043e\u043b\u043d\u0438\u0442\u0435\u043b\u044c\u043d\u043e: \u0443\u0441\u043b\u043e\u0432\u0438\u0435 A \u0434\u043e\u043f\u043e\u043b\u043d\u0438\u0442\u0435\u043b\u044c\u043d\u043e \u0441\u043a\u043e\u0440-\u0438\u0442\u0441\u044f \u0438 \u043d\u0430 validation-\u0441\u043f\u043b\u0438\u0442\u0435 \u043a\u0430\u043a \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0430 \u043f\u0435\u0440\u0435\u043d\u043e\u0441\u0430 (\u043e\u043f\u0443\u0431\u043b\u0438\u043a\u043e\u0432\u0430\u043d\u043d\u044b\u0435 \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u0438 \u043c\u043e\u0433\u043b\u0438 \u043d\u0430\u0441\u0442\u0440\u0430\u0438\u0432\u0430\u0442\u044c\u0441\u044f \u043d\u0430 BBH-\u0434\u0438\u0441\u0442\u0440\u0438\u0431\u0443\u0446\u0438\u0438, \u0432\u043a\u043b\u044e\u0447\u0430\u044f \u0442\u0435\u0441\u0442).\n7. **\u0418\u0441\u043f\u043e\u043b\u043d\u0435\u043d\u0438\u0435:** \u043f\u043e\u0440\u044f\u0434\u043e\u043a \u0432\u044b\u043f\u043e\u043b\u043d\u0435\u043d\u0438\u044f \u0443\u0441\u043b\u043e\u0432\u0438\u0439 \u0440\u0430\u043d\u0434\u043e\u043c\u0438\u0437\u0438\u0440\u043e\u0432\u0430\u043d (\u043f\u0440\u0438 \u0432\u043e\u0437\u043c\u043e\u0436\u043d\u043e\u0441\u0442\u0438), \u0447\u0442\u043e\u0431\u044b \u0438\u0441\u043a\u043b\u044e\u0447\u0438\u0442\u044c \u0441\u0438\u0441\u0442\u0435\u043c\u0430\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0439 \u0434\u0440\u0435\u0439\u0444 \u043c\u043e\u0434\u0435\u043b\u0438/\u043f\u0440\u043e\u0432\u0430\u0439\u0434\u0435\u0440\u0430 \u0432\u043e \u0432\u0440\u0435\u043c\u0435\u043d\u0438.\n\n---\n\n## (iv) \u0410\u043d\u0430\u043b\u0438\u0437 \u0434\u0430\u043d\u043d\u044b\u0445 \u0438 \u043a\u0440\u0438\u0442\u0435\u0440\u0438\u0439 \u0440\u0435\u0448\u0435\u043d\u0438\u044f\n\n**\u041f\u0435\u0440-\u0437\u0430\u0434\u0430\u0447\u043d\u044b\u0435 \u043c\u0435\u0442\u0440\u0438\u043a\u0438:** `acc_t(cond) = #correct_t(cond) / n_t` \u043f\u043e \u0442\u0435\u0441\u0442\u043e\u0432\u044b\u043c \u043f\u0440\u0438\u043c\u0435\u0440\u0430\u043c \u0437\u0430\u0434\u0430\u0447\u0438 t (t = 1..23), \u0441 \u0438\u0434\u0435\u043d\u0442\u0438\u0447\u043d\u044b\u043c \u0441\u043e\u043f\u043e\u0441\u0442\u0430\u0432\u043b\u0435\u043d\u0438\u0435\u043c \u00ab\u043f\u0440\u0438\u043c\u0435\u0440\u2192\u0443\u0441\u043b\u043e\u0432\u0438\u0435\u00bb.\n\n**\u0421\u0432\u043e\u0434\u043d\u044b\u0435:** \u0441\u0440\u0435\u0434\u043d\u044f\u044f \u0442\u043e\u0447\u043d\u043e\u0441\u0442\u044c \u043f\u043e 23 \u0437\u0430\u0434\u0430\u0447\u0430\u043c (\u043d\u0435\u0440\u0430\u0432\u043d\u043e-\u0432\u0437\u0432\u0435\u0448\u0435\u043d\u043d\u0430\u044f) `mean(acc_t)`, \u043c\u0435\u0434\u0438\u0430\u043d\u0430, \u0430\u0433\u0440\u0435\u0433\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u0430\u044f \u0442\u043e\u0447\u043d\u043e\u0441\u0442\u044c `sum(correct)/sum(n_t)`.\n\n**\u041f\u0430\u0440\u043d\u044b\u0435 \u0440\u0430\u0437\u043d\u043e\u0441\u0442\u0438:** `d_t(A,C1) = acc_t(A) \u2212 acc_t(C1)`, `d_t(A,C2) = acc_t(A) \u2212 acc_t(C2)`.\n\n**\u0421\u0442\u0430\u0442\u0438\u0441\u0442\u0438\u043a\u0430 (\u043f\u043e \u043a\u0430\u0436\u0434\u043e\u0439 \u043f\u0430\u0440\u0435 \u043e\u0442\u0434\u0435\u043b\u044c\u043d\u043e):**\n- **Wilcoxon signed-rank** \u043f\u043e 23 \u043f\u0435\u0440-\u0437\u0430\u0434\u0430\u0447\u043d\u044b\u043c \u0440\u0430\u0437\u043d\u043e\u0441\u0442\u044f\u043c (\u0434\u0432\u0443\u0441\u0442\u043e\u0440\u043e\u043d\u043d\u0438\u0439, \u03b1=0.05);\n- **\u0437\u043d\u0430\u043a\u043e\u0432\u044b\u0439 \u0442\u0435\u0441\u0442** (\u0447\u0438\u0441\u043b\u043e \u0437\u0430\u0434\u0430\u0447, \u0433\u0434\u0435 \u0440\u0430\u0437\u043d\u043e\u0441\u0442\u044c \u043f\u043e\u043b\u043e\u0436\u0438\u0442\u0435\u043b\u044c\u043d\u0430);\n- **\u0431\u0443\u0442\u0441\u0442\u0440\u0430\u043f \u043f\u043e \u0437\u0430\u0434\u0430\u0447\u0430\u043c:** 10 000 \u0440\u0435\u0441\u0435\u043c\u043f\u043b\u043e\u0432 \u0441 \u0432\u043e\u0437\u0432\u0440\u0430\u0442\u043e\u043c \u043d\u0430 23 \u0437\u0430\u0434\u0430\u0447\u0438, \u043f\u0435\u0440\u0446\u0435\u043d\u0442\u0438\u043b\u044c\u043d\u044b\u0439 95% CI \u0441\u0440\u0435\u0434\u043d\u0435\u0439 \u0440\u0430\u0437\u043d\u043e\u0441\u0442\u0438;\n- win/lose/tie-\u0442\u0430\u0431\u043b\u0438\u0446\u0430 \u043f\u043e \u0437\u0430\u0434\u0430\u0447\u0430\u043c \u0441 \u043f\u043e\u0440\u043e\u0433\u043e\u043c \u0441\u0443\u0449\u0435\u0441\u0442\u0432\u0435\u043d\u043d\u043e\u0441\u0442\u0438 \u22651 \u043f.\u043f.\n\n**\u041f\u0440\u0435-\u0440\u0435\u0433\u0438\u0441\u0442\u0440\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0439 \u043a\u0440\u0438\u0442\u0435\u0440\u0438\u0439 \u00aboutperform\u00bb (\u043f\u0435\u0440\u0432\u0438\u0447\u043d\u044b\u0439), \u0434\u043b\u044f \u043a\u0430\u0436\u0434\u043e\u0439 \u0431\u0430\u0437\u0438\u043b\u043a\u0438 \u043d\u0435\u0437\u0430\u0432\u0438\u0441\u0438\u043c\u043e:**\n> OPRO \u00aboutperforms\u00bb \u0431\u0430\u0437\u0438\u043b\u043a\u0443 \u21d4 (1) `mean(acc_t(A)) > mean(acc_t(C))`; (2) 95% \u0431\u0443\u0442\u0441\u0442\u0440\u0430\u043f-CI \u0441\u0440\u0435\u0434\u043d\u0435\u0439 \u0440\u0430\u0437\u043d\u043e\u0441\u0442\u0438 \u0438\u0441\u043a\u043b\u044e\u0447\u0430\u0435\u0442 0; (3) p_Wilcoxon < 0.05.\n\n**\u0412\u0442\u043e\u0440\u0438\u0447\u043d\u044b\u0439 \u043a\u0440\u0438\u0442\u0435\u0440\u0438\u0439 (\u044d\u0444\u0444\u0435\u043a\u0442-\u043f\u043e\u0440\u043e\u0433):** \u0440\u0430\u0437\u043d\u043e\u0441\u0442\u044c \u0441\u0440\u0435\u0434\u043d\u0438\u0445 \u2265 \u03b4, \u0433\u0434\u0435 \u03b4 = 1 \u043f.\u043f. (\u043f\u0440\u0435-\u0443\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u0435\u043d\u043e; \u043e\u0442\u0447\u0451\u0442 \u2014 \u0432\u0441\u0435\u0433\u0434\u0430, \u043d\u0435\u0437\u0430\u0432\u0438\u0441\u0438\u043c\u043e \u043e\u0442 \u0437\u043d\u0430\u0447\u0438\u043c\u043e\u0441\u0442\u0438). \u041f\u0440\u0438 n=23 CI \u2014 \u0433\u043b\u0430\u0432\u043d\u044b\u0439 \u0438\u0441\u0442\u043e\u0447\u043d\u0438\u043a \u0441\u0432\u0438\u0434\u0435\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u0430; \u0437\u043d\u0430\u0447\u0438\u043c\u043e\u0441\u0442\u044c \u2014 \u0432\u0441\u043f\u043e\u043c\u043e\u0433\u0430\u0442\u0435\u043b\u044c\u043d\u0430\u044f.\n\n**\u041c\u0443\u043b\u044c\u0442\u0438\u043f\u043b\u0438\u043a\u0430\u0442\u0438\u0432\u043d\u043e\u0441\u0442\u044c:** \u0434\u0432\u0430 \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u044f (C1, C2). \u041e\u0442\u0447\u0451\u0442 \u2014 \u00ab\u0441\u044b\u0440\u044b\u0435\u00bb p \u0441 \u043e\u0433\u043e\u0432\u043e\u0440\u043a\u043e\u0439 \u043e \u043c\u0443\u043b\u044c\u0442\u0438\u043f\u043b\u0438\u043a\u0430\u0442\u0438\u0432\u043d\u043e\u0441\u0442\u0438; \u043e\u043f\u0446\u0438\u043e\u043d\u0430\u043b\u044c\u043d\u043e \u0432\u0442\u043e\u0440\u0438\u0447\u043d\u0430\u044f \u0431\u043e\u043d\u0444\u0435\u0440\u0440\u043e\u043d\u0438\u0435\u0432\u0441\u043a\u0430\u044f \u043f\u043e\u043f\u0440\u0430\u0432\u043a\u0430 \u043d\u0430 2 \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u044f. \u0418\u0442\u043e\u0433 \u0444\u043e\u0440\u043c\u0443\u043b\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u043e\u0442\u0434\u0435\u043b\u044c\u043d\u043e \u043f\u043e H1 \u0438 \u043f\u043e H2 (\u043e\u0431\u044a\u0435\u0434\u0438\u043d\u0451\u043d\u043d\u044b\u0439 \u0432\u0435\u0440\u0434\u0438\u043a\u0442 \u00abOPRO \u043b\u0443\u0447\u0448\u0435 \u0431\u0430\u0437\u0438\u043b\u043e\u043a\u00bb \u043d\u0435 \u0432\u0432\u043e\u0434\u0438\u0442\u0441\u044f \u043a\u0430\u043a \u0435\u0434\u0438\u043d\u044b\u0439 \u043a\u0440\u0438\u0442\u0435\u0440\u0438\u0439).\n\n**\u041e\u0431\u0440\u0430\u0431\u043e\u0442\u043a\u0430 \u043f\u0440\u043e\u043f\u0443\u0441\u043a\u043e\u0432/\u0441\u0431\u043e\u0435\u0432 \u0438\u0437\u0432\u043b\u0435\u0447\u0435\u043d\u0438\u044f:** \u0441\u0431\u043e\u0439 = \u00ab\u043d\u0435\u0432\u0435\u0440\u043d\u043e\u00bb \u0432 \u043e\u0441\u043d\u043e\u0432\u043d\u043e\u043c \u0430\u043d\u0430\u043b\u0438\u0437\u0435; \u0447\u0443\u0432\u0441\u0442\u0432\u0438\u0442\u0435\u043b\u044c\u043d\u044b\u0439 \u0430\u043d\u0430\u043b\u0438\u0437 \u2014 \u0431\u0435\u0437 \u0443\u0447\u0451\u0442\u0430 \u043f\u0440\u0438\u043c\u0435\u0440\u043e\u0432 \u0441\u043e \u0441\u0431\u043e\u0435\u043c \u0438\u0437\u0432\u043b\u0435\u0447\u0435\u043d\u0438\u044f.\n\n**\u041e\u0442\u0447\u0451\u0442\u043d\u044b\u0435 \u0430\u0440\u0442\u0435\u0444\u0430\u043a\u0442\u044b:** \u0442\u0430\u0431\u043b\u0438\u0446\u0430 \u043f\u0435\u0440-\u0437\u0430\u0434\u0430\u0447\u043d\u044b\u0445 accuracy \u043f\u043e \u0432\u0441\u0435\u043c \u0443\u0441\u043b\u043e\u0432\u0438\u044f\u043c (A, A_meta (\u043f\u0440\u0438 \u043d\u0430\u043b\u0438\u0447\u0438\u0438), C1, C2, D); \u0442\u0430\u0431\u043b\u0438\u0446\u0430 \u043f\u0430\u0440\u043d\u044b\u0445 \u0440\u0430\u0437\u043d\u043e\u0441\u0442\u0435\u0439 \u0441 CI \u0438 p; win/lose/tie; \u043e\u0442\u0447\u0451\u0442 \u043e \u0441\u0431\u043e\u044f\u0445 \u0438\u0437\u0432\u043b\u0435\u0447\u0435\u043d\u0438\u044f; \u043e\u0442\u0447\u0451\u0442 \u043e \u0431\u044e\u0434\u0436\u0435\u0442\u0435 \u0432\u044b\u0437\u043e\u0432\u043e\u0432/\u0442\u043e\u043a\u0435\u043d\u043e\u0432; \u043f\u0440\u0435-\u0440\u0435\u0433\u0438\u0441\u0442\u0440\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u0430\u044f \u0432\u0435\u0440\u0441\u0438\u044f \u043f\u0440\u043e\u0442\u043e\u043a\u043e\u043b\u0430 (\u043a\u0440\u0438\u0442\u0435\u0440\u0438\u0439 \u0434\u043e \u043f\u0440\u043e\u0441\u043c\u043e\u0442\u0440\u0430 \u0442\u0435\u0441\u0442\u0430).\n\n---\n\n## (v) \u041e\u0441\u0443\u0449\u0435\u0441\u0442\u0432\u0438\u043c\u043e\u0441\u0442\u044c\n\n**\u0427\u0442\u043e \u0432\u044b\u043f\u043e\u043b\u043d\u0438\u043c\u043e \u041b\u041e\u041a\u0410\u041b\u042c\u041d\u041e \u0432 \u0442\u0435\u043a\u0443\u0449\u0435\u0439 \u043f\u0435\u0441\u043e\u0447\u043d\u0438\u0446\u0435 (stdlib Python 3.14, \u0431\u0435\u0437 \u043f\u0430\u043a\u0435\u0442\u043e\u0432, \u0431\u0435\u0437 \u0441\u0435\u0442\u0438):**\n- \u0440\u0435\u043f\u043b\u0435\u0439 \u043f\u0440\u0435\u0434\u0437\u0430\u043f\u0438\u0441\u0430\u043d\u043d\u044b\u0445 \u043b\u043e\u0433\u043e\u0432 \u0437\u0430\u0432\u0435\u0440\u0448\u0435\u043d\u0438\u0439 \u0438 \u0438\u0445 \u0434\u0435\u0442\u0435\u0440\u043c\u0438\u043d\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0439 \u0441\u043a\u043e\u0440\u0438\u043d\u0433 (\u043d\u043e\u0440\u043c\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u044f + exact match + bootstrap \u043d\u0430 `random`-\u043c\u043e\u0434\u0443\u043b\u0435);\n- \u0433\u0435\u043d\u0435\u0440\u0430\u0446\u0438\u044f \u0444\u0430\u0439\u043b\u043e\u0432 \u043f\u0440\u043e\u043c\u043f\u0442\u043e\u0432/\u0437\u0430\u043f\u0440\u043e\u0441\u043e\u0432 \u043f\u043e \u043e\u043f\u0438\u0441\u0430\u043d\u043d\u043e\u0439 \u0440\u0430\u0441\u043a\u043b\u0430\u0434\u043a\u0435;\n- \u0441\u043a\u0440\u0438\u043f\u0442-\u0441\u043a\u0435\u043b\u0435\u0442 \u043e\u0446\u0435\u043d\u043a\u0438 \u0438 \u0441\u0442\u0430\u0442\u0438\u0441\u0442\u0438\u043a\u0438; \u0441\u0430\u043c \u044d\u0442\u043e\u0442 \u0434\u0438\u0437\u0430\u0439\u043d-\u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442.\n\n**\u0427\u0442\u043e \u0442\u0440\u0435\u0431\u0443\u0435\u0442 \u0412\u041d\u0415\u0428\u041d\u0415\u0413\u041e \u043a\u0430\u043d\u0430\u043b\u0430 (\u0432 \u043f\u0435\u0441\u043e\u0447\u043d\u0438\u0446\u0435 \u041d\u0415\u0434\u043e\u0441\u0442\u0443\u043f\u043d\u043e \u2014 \u043f\u0440\u043e\u0432\u0435\u0440\u0435\u043d\u043e):**\n- \u0432\u0441\u0435 LLM-\u0432\u044b\u0437\u043e\u0432\u044b (\u043d\u0435\u0442 \u0441\u0435\u0442\u0438, API-\u043a\u043b\u044e\u0447\u0435\u0439, \u0432\u0435\u0441\u043e\u0432, GPU);\n- \u0441\u043a\u0430\u0447\u0438\u0432\u0430\u043d\u0438\u0435 BBH \u0438 \u0442\u0435\u043a\u0441\u0442\u043e\u0432 \u043e\u043f\u0443\u0431\u043b\u0438\u043a\u043e\u0432\u0430\u043d\u043d\u044b\u0445 \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u0439 OPRO.\n\n**\u0414\u0432\u0430 \u0440\u0435\u0436\u0438\u043c\u0430 \u0438\u0441\u043f\u043e\u043b\u043d\u0435\u043d\u0438\u044f:**\n- **\u0420\u0435\u0436\u0438\u043c A \u2014 \u0432\u043d\u0435\u0448\u043d\u0438\u0439 API \u0441 \u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u043c \u0431\u044e\u0434\u0436\u0435\u0442\u043e\u043c:** \u0431\u044e\u0434\u0436\u0435\u0442 (\u0447\u0438\u0441\u043b\u043e \u0432\u044b\u0437\u043e\u0432\u043e\u0432/\u0442\u043e\u043a\u0435\u043d\u043e\u0432) \u2014 \u0441\u043c. \u043d\u0438\u0436\u0435; \u043b\u043e\u0433\u0438 \u0437\u0430\u043f\u0438\u0441\u044b\u0432\u0430\u044e\u0442\u0441\u044f \u0438 \u0437\u0430\u0442\u0435\u043c \u0441\u043a\u043e\u0440\u044f\u0442\u0441\u044f \u043b\u043e\u043a\u0430\u043b\u044c\u043d\u043e.\n- **\u0420\u0435\u0436\u0438\u043c B \u2014 \u043f\u0440\u0435\u0434\u0437\u0430\u043f\u0438\u0441\u0430\u043d\u043d\u044b\u0435 \u043b\u043e\u0433\u0438:** \u0432\u043d\u0435\u0448\u043d\u044f\u044f \u0441\u0442\u043e\u0440\u043e\u043d\u0430 \u0433\u0435\u043d\u0435\u0440\u0438\u0440\u0443\u0435\u0442 \u043f\u043e\u043b\u043d\u044b\u0435 \u043b\u043e\u0433\u0438 \u0437\u0430\u0432\u0435\u0440\u0448\u0435\u043d\u0438\u0439 \u043f\u043e \u0441\u043f\u0435\u0446\u0438\u0444\u0438\u043a\u0430\u0446\u0438\u0438 \u043f\u0440\u043e\u043c\u043f\u0442\u043e\u0432; \u043b\u043e\u043a\u0430\u043b\u044c\u043d\u043e \u0432\u044b\u043f\u043e\u043b\u043d\u044f\u0435\u0442\u0441\u044f \u0442\u043e\u043b\u044c\u043a\u043e \u0440\u0435\u043f\u043b\u0435\u0439+\u0441\u043a\u043e\u0440\u0438\u043d\u0433 (\u0435\u0434\u0438\u043d\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0439 \u043f\u0443\u0442\u044c, \u043f\u043e\u043b\u043d\u043e\u0441\u0442\u044c\u044e \u0432\u044b\u043f\u043e\u043b\u043d\u0438\u043c\u044b\u0439 \u0432 \u043f\u0435\u0441\u043e\u0447\u043d\u0438\u0446\u0435).\n\n**\u041e\u0446\u0435\u043d\u043a\u0430 \u043e\u0431\u044a\u0451\u043c\u0430 \u0432\u044b\u0437\u043e\u0432\u043e\u0432/\u0442\u043e\u043a\u0435\u043d\u043e\u0432 (\u0444\u043e\u0440\u043c\u0443\u043b\u044b; \u043f\u043e\u0440\u044f\u0434\u043e\u043a \u0432\u0435\u043b\u0438\u0447\u0438\u043d\u044b \u2014 \u043e\u0446\u0435\u043d\u043a\u0430, \u043d\u0435 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442):**\n- \u0422\u0435\u0441\u0442\u043e\u0432\u0430\u044f \u043e\u0446\u0435\u043d\u043a\u0430 \u043e\u0441\u043d\u043e\u0432\u043d\u044b\u0445 \u0443\u0441\u043b\u043e\u0432\u0438\u0439 (A, C1, C2; D \u2014 \u043e\u043f\u0446\u0438\u043e\u043d\u0430\u043b\u044c\u043d\u043e): `cond_count \u00d7 23 \u0437\u0430\u0434\u0430\u0447 \u00d7 \u03a3_t n_t(\u0442\u0435\u0441\u0442)`. \u041f\u0440\u0438 ~250/\u0437\u0430\u0434\u0430\u0447\u0443 \u0438 3 \u0443\u0441\u043b\u043e\u0432\u0438\u044f\u0445: \u2248 17 250 \u0432\u044b\u0437\u043e\u0432\u043e\u0432 (+ \u22485 750, \u0435\u0441\u043b\u0438 \u0432\u043a\u043b\u044e\u0447\u0430\u0435\u0442\u0441\u044f D). \u0412\u0445\u043e\u0434 \u043d\u0430 \u0432\u044b\u0437\u043e\u0432 \u2014 \u044d\u043a\u0437\u044d\u043c\u043f\u043b\u044f\u0440\u044b+\u043f\u0440\u0438\u043c\u0435\u0440 (\u0437\u0430\u0432\u0438\u0441\u0438\u0442 \u043e\u0442 \u0434\u043b\u0438\u043d\u044b \u044d\u043a\u0437\u044d\u043c\u043f\u043b\u044f\u0440\u043e\u0432, \u043e\u0440\u0438\u0435\u043d\u0442\u0438\u0440\u043e\u0432\u043e\u0447\u043d\u043e 0.5\u20131.5k \u0442\u043e\u043a\u0435\u043d\u043e\u0432); \u0432\u044b\u0445\u043e\u0434 \u2014 \u0437\u0430\u0432\u0438\u0441\u044f\u0449\u0438\u0439 \u043e\u0442 \u0443\u0441\u043b\u043e\u0432\u0438\u044f (\u043a\u0440\u0430\u0442\u043a\u0438\u0439 \u0434\u043b\u044f C2, CoT \u0434\u043b\u044f A/C1). \u0421\u0443\u043c\u043c\u0430\u0440\u043d\u044b\u0435 \u0442\u043e\u043a\u0435\u043d\u044b \u0440\u0430\u0441\u0441\u0447\u0438\u0442\u044b\u0432\u0430\u044e\u0442\u0441\u044f \u0444\u0430\u043a\u0442\u0438\u0447\u0435\u0441\u043a\u0438 \u043f\u043e \u0434\u043b\u0438\u043d\u0430\u043c \u044d\u043a\u0437\u044d\u043c\u043f\u043b\u044f\u0440\u043e\u0432 \u0438 \u043b\u043e\u0433\u0438\u0440\u0443\u044e\u0442\u0441\u044f \u0432 \u043e\u0442\u0447\u0451\u0442\u0435.\n- \u0410\u0440\u043c \u043f\u0435\u0440\u0435-\u043e\u043f\u0442\u0438\u043c\u0438\u0437\u0430\u0446\u0438\u0438 (\u043e\u043f\u0446\u0438\u043e\u043d\u0430\u043b\u044c\u043d\u043e): `steps \u00d7 candidates` \u0432\u044b\u0437\u043e\u0432\u043e\u0432 \u043e\u043f\u0442\u0438\u043c\u0438\u0437\u0430\u0442\u043e\u0440\u0430 + `steps \u00d7 candidates \u00d7 val_examples` \u0441\u043a\u043e\u0440\u0438\u043d\u0433\u043e\u0432\u044b\u0445 \u0432\u044b\u0437\u043e\u0432\u043e\u0432 \u043d\u0430 \u0437\u0430\u0434\u0430\u0447\u0443; \u043f\u0440\u0438 \u0440\u0435\u043a\u043e\u043c\u0435\u043d\u0434\u0443\u0435\u043c\u043e\u043c \u0431\u044e\u0434\u0436\u0435\u0442\u0435 `20\u00d7100\u00d78` \u043d\u0430 \u0437\u0430\u0434\u0430\u0447\u0443 \u2248 2 000 + 16 000 \u0432\u044b\u0437\u043e\u0432\u043e\u0432/\u0437\u0430\u0434\u0430\u0447\u0443 (\u2248 414k \u0441\u043a\u043e\u0440\u0438\u043d\u0433\u043e\u0432\u044b\u0445 \u0432\u044b\u0437\u043e\u0432\u043e\u0432 \u043d\u0430 23 \u0437\u0430\u0434\u0430\u0447\u0438 \u2014 \u0441\u0443\u0449\u0435\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0439 \u043e\u0431\u044a\u0451\u043c; \u043f\u0440\u0438 \u0434\u0435\u0444\u0438\u0446\u0438\u0442\u0435 \u0431\u044e\u0434\u0436\u0435\u0442 \u0441\u043d\u0438\u0436\u0430\u0435\u0442\u0441\u044f \u0438 \u0444\u0438\u043a\u0441\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u0432 \u043e\u0442\u0447\u0451\u0442\u0435).\n- \u041f\u043e\u0432\u0442\u043e\u0440\u043d\u044b\u0435 \u043f\u0440\u043e\u0433\u043e\u043d\u044b (\u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044c \u0440\u0430\u0437\u0431\u0440\u043e\u0441\u0430): \u00d73 \u043f\u0440\u0438 \u043d\u0430\u043b\u0438\u0447\u0438\u0438 \u0431\u044e\u0434\u0436\u0435\u0442\u0430.\n\n**\u041f\u043e\u0440\u044f\u0434\u043e\u043a \u0438\u0441\u043f\u043e\u043b\u043d\u0435\u043d\u0438\u044f \u043f\u043e\u0441\u043b\u0435 \u043f\u0440\u0435\u0434\u043e\u0441\u0442\u0430\u0432\u043b\u0435\u043d\u0438\u044f \u0440\u0435\u0441\u0443\u0440\u0441\u043e\u0432:** (1) \u0444\u0438\u043a\u0441\u0430\u0446\u0438\u044f \u0438\u0441\u0442\u043e\u0447\u043d\u0438\u043a\u0430 BBH, \u043c\u043e\u0434\u0435\u043b\u0438, \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u0439 OPRO \u0438 \u043a\u0440\u0438\u0442\u0435\u0440\u0438\u044f; (2) \u0441\u0431\u043e\u0440\u043a\u0430 \u043f\u0440\u043e\u043c\u043f\u0442\u043e\u0432; (3) \u0432\u043d\u0435\u0448\u043d\u044f\u044f \u0433\u0435\u043d\u0435\u0440\u0430\u0446\u0438\u044f \u043b\u043e\u0433\u043e\u0432 (\u0440\u0435\u0436\u0438\u043c A \u0438\u043b\u0438 B); (4) \u043b\u043e\u043a\u0430\u043b\u044c\u043d\u044b\u0439 \u0441\u043a\u043e\u0440\u0438\u043d\u0433 \u0438 \u0441\u0442\u0430\u0442\u0438\u0441\u0442\u0438\u043a\u0430; (5) \u043e\u0442\u0447\u0451\u0442. \u041d\u0438\u043a\u0430\u043a\u043e\u0439 \u0448\u0430\u0433 \u043d\u0435 \u0432\u044b\u043f\u043e\u043b\u043d\u0435\u043d \u0432 \u0440\u0430\u043c\u043a\u0430\u0445 \u044d\u0442\u043e\u0433\u043e \u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442\u0430.\n\n---\n\n## (vi) \u041e\u0433\u0440\u0430\u043d\u0438\u0447\u0435\u043d\u0438\u044f \u0438 \u0434\u043e\u043f\u0443\u0449\u0435\u043d\u0438\u044f\n\n**\u0417\u0430\u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0435 \u0434\u043e\u043f\u0443\u0449\u0435\u043d\u0438\u044f (\u043f\u0440\u043e\u0442\u043e\u043a\u043e\u043b):**\n1. \u041e\u0434\u043d\u0430 \u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u0430\u044f scorer-\u043c\u043e\u0434\u0435\u043b\u044c; \u0432\u0430\u0440\u044c\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u0442\u043e\u043b\u044c\u043a\u043e \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u044f.\n2. OPRO-\u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u0438 = \u043e\u043f\u0443\u0431\u043b\u0438\u043a\u043e\u0432\u0430\u043d\u043d\u044b\u0435 \u0432 \u0441\u0442\u0430\u0442\u044c\u0435 \u043f\u0435\u0440-\u0437\u0430\u0434\u0430\u0447\u043d\u044b\u0435 \u0441\u0442\u0440\u043e\u043a\u0438 (\u0433\u043e\u043b\u043e\u0432\u043d\u043e\u0439 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442); \u043f\u0435\u0440\u0435-\u043e\u043f\u0442\u0438\u043c\u0438\u0437\u0430\u0446\u0438\u044f \u2014 \u043e\u043f\u0446\u0438\u043e\u043d\u0430\u043b\u044c\u043d\u044b\u0439 arm \u043d\u0430\u0434\u0451\u0436\u043d\u043e\u0441\u0442\u0438 \u043d\u0430 validation, \u0441\u0442\u0440\u043e\u0433\u043e \u043e\u0442\u0434\u0435\u043b\u044c\u043d\u043e \u043e\u0442 test; \u043f\u0440\u0438 \u043e\u0442\u0441\u0443\u0442\u0441\u0442\u0432\u0438\u0438 \u0438\u043d\u0444\u0440\u0430\u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u044b \u0430\u0440\u043c \u0438\u0441\u043a\u043b\u044e\u0447\u0430\u0435\u0442\u0441\u044f \u0438 \u044d\u0442\u043e \u0444\u0438\u043a\u0441\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u0432 \u043e\u0442\u0447\u0451\u0442\u0435.\n3. \u0411\u0430\u0437\u0438\u043b\u043a\u0438 \u0431\u0443\u043a\u0432\u0430\u043b\u044c\u043d\u043e \u043f\u043e \u0432\u043e\u043f\u0440\u043e\u0441\u0443: \u00abLet's think step by step.\u00bb \u0438 \u043f\u0443\u0441\u0442\u043e\u0439 \u043f\u0440\u043e\u043c\u043f\u0442, \u043a\u0430\u0436\u0434\u0430\u044f \u0432 \u043f\u0430\u0440\u0435 \u0441 \u0442\u0435\u043c\u0438 \u0436\u0435 BBH-\u044d\u043a\u0437\u044d\u043c\u043f\u043b\u044f\u0440\u0430\u043c\u0438, \u0447\u0442\u043e \u0438 \u0443\u0441\u043b\u043e\u0432\u0438\u0435 A; \u0447\u0435\u043b\u043e\u0432\u0435\u0447\u0435\u0441\u043a\u0438\u0435 CoT-\u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u0438 BBH \u2014 \u0442\u043e\u043b\u044c\u043a\u043e \u0440\u0435\u0444\u0435\u0440\u0435\u043d\u0441 D.\n4. \u00ab\u0418\u0441\u0442\u0438\u043d\u0430\u00bb \u0434\u043b\u044f BBH = \u043e\u0444\u0438\u0446\u0438\u0430\u043b\u044c\u043d\u044b\u0435 \u043c\u0435\u0442\u043a\u0438 test-\u0441\u043f\u043b\u0438\u0442\u0430; \u043e\u043f\u0435\u0440\u0430\u0446\u0438\u043e\u043d\u0430\u043b \u2014 exact match \u043f\u043e \u043d\u043e\u0440\u043c\u0430\u043b\u0438\u0437\u043e\u0432\u0430\u043d\u043d\u043e\u043c\u0443 \u043e\u0442\u0432\u0435\u0442\u0443.\n5. \u041f\u0430\u0440\u043d\u044b\u0439 \u0434\u0438\u0437\u0430\u0439\u043d \u00ab\u043f\u0440\u0438\u043c\u0435\u0440\u2192\u0443\u0441\u043b\u043e\u0432\u0438\u0435\u00bb; \u0435\u0434\u0438\u043d\u044b\u0439 \u043a\u043e\u0434 \u043d\u043e\u0440\u043c\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u0438/\u0441\u043a\u043e\u0440\u0438\u043d\u0433\u0430; \u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0439 \u0434\u0435\u043a\u043e\u0434\u0438\u043d\u0433; \u0440\u0430\u0441\u043a\u0440\u044b\u0442\u0438\u0435 \u0431\u044e\u0434\u0436\u0435\u0442\u0430.\n6. \u041a\u0440\u0438\u0442\u0435\u0440\u0438\u0439 \u00aboutperform\u00bb \u043f\u0440\u0435-\u0440\u0435\u0433\u0438\u0441\u0442\u0440\u0438\u0440\u043e\u0432\u0430\u043d: \u0441\u0440\u0435\u0434\u043d\u044f\u044f > \u0431\u0430\u0437\u0438\u043b\u043a\u0438 \u0418 95% \u0431\u0443\u0442\u0441\u0442\u0440\u0430\u043f-CI \u0438\u0441\u043a\u043b\u044e\u0447\u0430\u0435\u0442 0 \u0418 p<0.05; \u043f\u043b\u044e\u0441 \u044d\u0444\u0444\u0435\u043a\u0442-\u043f\u043e\u0440\u043e\u0433 \u03b4=1 \u043f.\u043f.\n\n**\u041e\u0441\u043e\u0437\u043d\u0430\u043d\u043d\u044b\u0435 \u043e\u0433\u0440\u0430\u043d\u0438\u0447\u0435\u043d\u0438\u044f \u0434\u0438\u0437\u0430\u0439\u043d\u0430:**\n- \u041e\u043f\u0443\u0431\u043b\u0438\u043a\u043e\u0432\u0430\u043d\u043d\u044b\u0435 \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u0438 OPRO \u043d\u0430\u0441\u0442\u0440\u0430\u0438\u0432\u0430\u043b\u0438\u0441\u044c \u043d\u0430 BBH-\u0434\u0438\u0441\u0442\u0440\u0438\u0431\u0443\u0446\u0438\u0438 (\u0432\u043a\u043b\u044e\u0447\u0430\u044f, \u0432\u043e\u0437\u043c\u043e\u0436\u043d\u043e, \u0442\u0435\u0441\u0442) \u2192 \u044d\u0442\u043e \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0430 \u043f\u0435\u0440\u0435\u043d\u043e\u0441\u0430, \u0430 \u043d\u0435 \u0432\u043d\u0443\u0442\u0440\u0438\u043c\u043e\u0434\u0435\u043b\u044c\u043d\u043e\u0439 \u043e\u043f\u0442\u0438\u043c\u0438\u0437\u0430\u0446\u0438\u0438; \u0441\u043c\u044f\u0433\u0447\u0430\u0435\u0442\u0441\u044f \u0434\u043e\u043f\u043e\u043b\u043d\u0438\u0442\u0435\u043b\u044c\u043d\u044b\u043c \u0441\u043a\u043e\u0440\u0438\u043d\u0433\u043e\u043c \u043d\u0430 validation.\n- \u041e\u0446\u0435\u043d\u043a\u0430 \u043f\u0435\u0440\u0435\u043d\u043e\u0441\u0430 \u043d\u0430 \u043c\u043e\u0434\u0435\u043b\u044c \u2260 PaLM 2-L \u043c\u0435\u043d\u044f\u0435\u0442 \u0438\u043d\u0442\u0435\u0440\u043f\u0440\u0435\u0442\u0430\u0446\u0438\u044e \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u0430 (\u043f\u0435\u0440\u0435\u043d\u043e\u0441 vs \u043e\u043f\u0442\u0438\u043c\u0438\u0437\u0430\u0446\u0438\u044f).\n- n=23 \u0437\u0430\u0434\u0430\u0447 \u2014 \u043c\u0430\u043b\u043e \u0434\u043b\u044f \u0447\u0430\u0441\u0442\u043e\u0442\u043d\u044b\u0445 \u0442\u0435\u0441\u0442\u043e\u0432; \u0448\u0438\u0440\u043e\u043a\u0438\u0435 CI; \u0437\u043d\u0430\u0447\u0438\u043c\u043e\u0441\u0442\u044c \u2014 \u0432\u0442\u043e\u0440\u0438\u0447\u043d\u044b\u0439 \u043a\u0440\u0438\u0442\u0435\u0440\u0438\u0439.\n- \u0421\u0431\u043e\u0439 \u0438\u0437\u0432\u043b\u0435\u0447\u0435\u043d\u0438\u044f \u0443\u0447\u0438\u0442\u044b\u0432\u0430\u0435\u0442\u0441\u044f \u043a\u0430\u043a \u00ab\u043d\u0435\u0432\u0435\u0440\u043d\u043e\u00bb (\u0441 \u0430\u0431\u0438\u043b\u044f\u0446\u0438\u0435\u0439).\n\n**\u0412\u043d\u0435\u0448\u043d\u0438\u0435 \u043d\u0435\u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0451\u043d\u043d\u043e\u0441\u0442\u0438 (\u0442\u0440\u0435\u0431\u0443\u044e\u0442 \u0440\u0435\u0448\u0435\u043d\u0438\u044f \u0432\u043d\u0435 \u043f\u0435\u0441\u043e\u0447\u043d\u0438\u0446\u044b; \u043f\u0440\u0438 \u0438\u0445 \u043e\u0442\u0441\u0443\u0442\u0441\u0442\u0432\u0438\u0438 \u0434\u0438\u0437\u0430\u0439\u043d \u043e\u0441\u0442\u0430\u0451\u0442\u0441\u044f \u0431\u0443\u043c\u0430\u0436\u043d\u044b\u043c):**\n1. **\u0424\u0438\u0437\u0438\u0447\u0435\u0441\u043a\u0438\u0439 LLM-\u043a\u0430\u043d\u0430\u043b** (\u0432\u043d\u0435\u0448\u043d\u0438\u0439 API+\u0431\u044e\u0434\u0436\u0435\u0442 vs \u043f\u0440\u0435\u0434\u0437\u0430\u043f\u0438\u0441\u0430\u043d\u043d\u044b\u0435 \u043b\u043e\u0433\u0438) \u2014 \u043d\u0435\u0440\u0430\u0437\u0440\u0435\u0448\u0438\u043c\u043e \u0432 \u043f\u0435\u0441\u043e\u0447\u043d\u0438\u0446\u0435 (\u043d\u0435\u0442 \u0441\u0435\u0442\u0438/\u043a\u043b\u044e\u0447\u0435\u0439/GPU/\u043f\u0430\u043a\u0435\u0442\u043e\u0432).\n2. **\u0418\u0441\u0442\u043e\u0447\u043d\u0438\u043a \u0438 \u0442\u043e\u0447\u043d\u044b\u0435 \u0442\u0435\u043a\u0441\u0442\u044b \u043e\u043f\u0443\u0431\u043b\u0438\u043a\u043e\u0432\u0430\u043d\u043d\u044b\u0445 \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u0439 OPRO** \u0438 \u043d\u0430\u043b\u0438\u0447\u0438\u0435/\u0441\u0442\u0440\u043e\u043a\u0430 \u0433\u043b\u043e\u0431\u0430\u043b\u044c\u043d\u043e\u0439 \u043c\u0435\u0442\u0430-\u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u0438 (\u043f\u0440\u0438\u043b\u043e\u0436\u0435\u043d\u0438\u0435 \u0441\u0442\u0430\u0442\u044c\u0438 / \u0440\u0435\u043f\u043e\u0437\u0438\u0442\u043e\u0440\u0438\u0439 \u0432\u043e\u0441\u043f\u0440\u043e\u0438\u0437\u0432\u0435\u0434\u0435\u043d\u0438\u044f; \u0432 /workspace \u043e\u0442\u0441\u0443\u0442\u0441\u0442\u0432\u0443\u044e\u0442).\n3. **\u0412\u044b\u0431\u043e\u0440 scorer-\u043c\u043e\u0434\u0435\u043b\u0438** \u0438 \u0435\u0451 \u0434\u043e\u0441\u0442\u0443\u043f\u043d\u043e\u0441\u0442\u044c (PaLM 2-L \u043b\u0435\u0433\u0430\u0441\u0438; \u043d\u0443\u0436\u0435\u043d \u0432\u043d\u0435\u0448\u043d\u0438\u0439 \u0432\u044b\u0431\u043e\u0440 \u0441 \u0437\u0430\u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u043e\u0439 \u0432\u0435\u0440\u0441\u0438\u0435\u0439).\n4. **\u041a\u0430\u043d\u043e\u043d\u0438\u0447\u0435\u0441\u043a\u0438\u0439 \u0438\u0441\u0442\u043e\u0447\u043d\u0438\u043a BBH** \u0438 \u0442\u043e\u0447\u043d\u044b\u0435 \u043f\u0435\u0440-\u0437\u0430\u0434\u0430\u0447\u043d\u044b\u0435 \u0447\u0438\u0441\u043b\u0430 \u0442\u0435\u0441\u0442\u043e\u0432\u044b\u0445 \u043f\u0440\u0438\u043c\u0435\u0440\u043e\u0432; \u0432\u0435\u0440\u0441\u0438\u044f \u0438\u0441\u0442\u043e\u0447\u043d\u0438\u043a\u0430.\n5. **\u0422\u043e\u0447\u043d\u0430\u044f \u0441\u043f\u0435\u0446\u0438\u0444\u0438\u043a\u0430\u0446\u0438\u044f \u0431\u044e\u0434\u0436\u0435\u0442\u0430 OPRO \u0432 \u0441\u0442\u0430\u0442\u044c\u0435** (\u0447\u0438\u0441\u043b\u043e \u044d\u043a\u0437\u044d\u043c\u043f\u043b\u044f\u0440\u043e\u0432, \u0448\u0430\u0433\u043e\u0432, \u043a\u0430\u043d\u0434\u0438\u0434\u0430\u0442\u043e\u0432) \u2014 \u043d\u0443\u0436\u043d\u0430 \u0441\u0432\u0435\u0440\u043a\u0430 \u0441 \u0442\u0435\u043a\u0441\u0442\u043e\u043c \u0434\u043b\u044f \u0442\u043e\u0447\u043d\u043e\u0433\u043e \u0432\u043e\u0441\u043f\u0440\u043e\u0438\u0437\u0432\u0435\u0434\u0435\u043d\u0438\u044f \u0430\u0440\u043c\u0430 \u043f\u0435\u0440\u0435-\u043e\u043f\u0442\u0438\u043c\u0438\u0437\u0430\u0446\u0438\u0438.\n6. **\u041d\u0430\u043b\u0438\u0447\u0438\u0435 \u0431\u044e\u0434\u0436\u0435\u0442\u0430** \u043d\u0430 \u043f\u043e\u0432\u0442\u043e\u0440\u043d\u044b\u0435 \u043f\u0440\u043e\u0433\u043e\u043d\u044b \u0438 \u043d\u0430 \u0430\u0440\u043c \u043f\u0435\u0440\u0435-\u043e\u043f\u0442\u0438\u043c\u0438\u0437\u0430\u0446\u0438\u0438.\n\n**\u042d\u0442\u043e\u0442 \u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442 \u043d\u0435 \u0441\u043e\u0434\u0435\u0440\u0436\u0438\u0442 \u0438 \u043d\u0435 \u043f\u043e\u0434\u0440\u0430\u0437\u0443\u043c\u0435\u0432\u0430\u0435\u0442 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u043e\u0432 \u044d\u043a\u0441\u043f\u0435\u0440\u0438\u043c\u0435\u043d\u0442\u0430; \u0435\u0433\u043e \u0438\u0441\u043f\u043e\u043b\u043d\u0435\u043d\u0438\u0435 \u0432\u043e\u0437\u043c\u043e\u0436\u043d\u043e \u0442\u043e\u043b\u044c\u043a\u043e \u043f\u043e\u0441\u043b\u0435 \u043f\u0440\u0435\u0434\u043e\u0441\u0442\u0430\u0432\u043b\u0435\u043d\u0438\u044f \u0432\u043d\u0435\u0448\u043d\u0438\u0445 \u0440\u0435\u0441\u0443\u0440\u0441\u043e\u0432 \u0438\u0437 \u0440\u0430\u0437\u0434\u0435\u043b\u0430 (v)/(vi).**", "evidence": "\u0418\u043d\u0441\u043f\u0435\u043a\u0446\u0438\u044f: /workspace \u0441\u043e\u0434\u0435\u0440\u0436\u0438\u0442 \u0442\u043e\u043b\u044c\u043a\u043e task.json (445B) \u0441 \u0432\u043e\u043f\u0440\u043e\u0441\u043e\u043c \u0438 track.md \u00abDesign-only task; repositories and compute are not required\u00bb. \u041f\u043e\u0438\u0441\u043a \u043f\u043e / \u0437\u0430 bbh/bigbench/huggingface/*.jsonl \u043f\u0443\u0441\u0442. pip-\u0441\u043f\u0438\u0441\u043e\u043a: \u0442\u043e\u043b\u044c\u043a\u043e \u0441\u0438\u0441\u0442\u0435\u043c\u043d\u044b\u0435 \u043f\u0430\u043a\u0435\u0442\u044b \u0438 stdlib Python 3.14.4; torch/transformers/datasets/openai/anthropic/numpy/pandas \u043e\u0442\u0441\u0443\u0442\u0441\u0442\u0432\u0443\u044e\u0442. urllib \u2192 \u00abTemporary failure in name resolution\u00bb (\u0441\u0435\u0442\u044c off). env \u0431\u0435\u0437 API-\u043a\u043b\u044e\u0447\u0435\u0439/\u043f\u0440\u043e\u043a\u0441\u0438; nvidia-smi \u043e\u0442\u0441\u0443\u0442\u0441\u0442\u0432\u0443\u0435\u0442; home \u043f\u0443\u0441\u0442. \u041f\u0443\u0431\u043b\u0438\u0447\u043d\u044b\u0435 \u0438\u0441\u0442\u043e\u0447\u043d\u0438\u043a\u0438 (\u0442\u0440\u0435\u0431\u0443\u044e\u0442 \u0441\u0432\u0435\u0440\u043a\u0438): OPRO = arXiv:2309.03409 (\u043f\u0435\u0440-\u0437\u0430\u0434\u0430\u0447\u043d\u044b\u0435 \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u0438 \u0432 \u043f\u0440\u0438\u043b\u043e\u0436\u0435\u043d\u0438\u0438), BBH = 23 \u0437\u0430\u0434\u0430\u0447\u0438, few-shot CoT, exact-match, ~250 \u0442\u0435\u0441\u0442\u043e\u0432\u044b\u0445 \u043f\u0440\u0438\u043c\u0435\u0440\u043e\u0432/\u0437\u0430\u0434\u0430\u0447\u0443.", "assumptions": ["LLM-\u0432\u044b\u0437\u043e\u0432\u044b \u2014 \u0432\u043d\u0435 \u043f\u0435\u0441\u043e\u0447\u043d\u0438\u0446\u044b (\u0432\u043d\u0435\u0448\u043d\u0438\u0439 API \u0441 \u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u043c \u0431\u044e\u0434\u0436\u0435\u0442\u043e\u043c \u043b\u0438\u0431\u043e \u043f\u0440\u0435\u0434\u0437\u0430\u043f\u0438\u0441\u0430\u043d\u043d\u044b\u0435 \u043b\u043e\u0433\u0438; \u043b\u043e\u043a\u0430\u043b\u044c\u043d\u043e \u0432\u044b\u043f\u043e\u043b\u043d\u0438\u043c \u0442\u043e\u043b\u044c\u043a\u043e \u0440\u0435\u043f\u043b\u0435\u0439 \u043b\u043e\u0433\u043e\u0432 \u043d\u0430 stdlib)", "\u041e\u0434\u043d\u0430 \u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u0430\u044f scorer-\u043c\u043e\u0434\u0435\u043b\u044c; \u0432\u0430\u0440\u044c\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u0442\u043e\u043b\u044c\u043a\u043e \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u044f; \u0432\u044b\u0431\u043e\u0440 \u043c\u043e\u0434\u0435\u043b\u0438 \u0432\u043d\u0435\u0448\u043d\u0438\u0439", "OPRO-\u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u0438 = \u043e\u043f\u0443\u0431\u043b\u0438\u043a\u043e\u0432\u0430\u043d\u043d\u044b\u0435 \u0432 \u0441\u0442\u0430\u0442\u044c\u0435 \u043f\u0435\u0440-\u0437\u0430\u0434\u0430\u0447\u043d\u044b\u0435 \u0441\u0442\u0440\u043e\u043a\u0438 (\u0433\u043e\u043b\u043e\u0432\u043d\u043e\u0439 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442); \u043f\u0435\u0440\u0435-\u043e\u043f\u0442\u0438\u043c\u0438\u0437\u0430\u0446\u0438\u044f \u2014 \u043e\u043f\u0446\u0438\u043e\u043d\u0430\u043b\u044c\u043d\u044b\u0439 arm \u043d\u0430 validation, \u0441\u0442\u0440\u043e\u0433\u043e \u043e\u0442\u0434\u0435\u043b\u044c\u043d\u043e \u043e\u0442 test", "\u0411\u0430\u0437\u0438\u043b\u043a\u0438 \u0431\u0443\u043a\u0432\u0430\u043b\u044c\u043d\u043e: \u00abLet's think step by step.\u00bb \u0438 \u043f\u0443\u0441\u0442\u043e\u0439 \u043f\u0440\u043e\u043c\u043f\u0442, \u043a\u0430\u0436\u0434\u0430\u044f \u0441 \u0442\u0435\u043c\u0438 \u0436\u0435 BBH-\u044d\u043a\u0437\u044d\u043c\u043f\u043b\u044f\u0440\u0430\u043c\u0438; \u0447\u0435\u043b\u043e\u0432\u0435\u0447\u0435\u0441\u043a\u0438\u0435 CoT-\u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u0438 BBH \u2014 \u0442\u043e\u043b\u044c\u043a\u043e \u0440\u0435\u0444\u0435\u0440\u0435\u043d\u0441 D", "\u0418\u0441\u0442\u0438\u043d\u0430 \u0434\u043b\u044f BBH = \u043e\u0444\u0438\u0446\u0438\u0430\u043b\u044c\u043d\u044b\u0435 \u043c\u0435\u0442\u043a\u0438 test-\u0441\u043f\u043b\u0438\u0442\u0430; \u043e\u043f\u0435\u0440\u0430\u0446\u0438\u043e\u043d\u0430\u043b = exact match \u043f\u043e \u043d\u043e\u0440\u043c\u0430\u043b\u0438\u0437\u043e\u0432\u0430\u043d\u043d\u043e\u043c\u0443 \u043e\u0442\u0432\u0435\u0442\u0443", "\u041a\u0440\u0438\u0442\u0435\u0440\u0438\u0439 \u00aboutperform\u00bb \u043f\u0440\u0435-\u0440\u0435\u0433\u0438\u0441\u0442\u0440\u0438\u0440\u043e\u0432\u0430\u043d (mean>, CI \u0438\u0441\u043a\u043b\u044e\u0447\u0430\u0435\u0442 0, p<0.05) \u043f\u043b\u044e\u0441 \u044d\u0444\u0444\u0435\u043a\u0442-\u043f\u043e\u0440\u043e\u0433 \u03b4=1 \u043f.\u043f.", "\u0412\u0441\u0435 23 \u0437\u0430\u0434\u0430\u0447\u0438 BBH, \u043e\u0444\u0438\u0446\u0438\u0430\u043b\u044c\u043d\u044b\u0439 test-\u0441\u043f\u043b\u0438\u0442, \u0432\u0441\u0435 \u043f\u0440\u0438\u043c\u0435\u0440\u044b (~250/\u0437\u0430\u0434\u0430\u0447\u0443), \u043f\u0430\u0440\u043d\u044b\u0439 \u0434\u0438\u0437\u0430\u0439\u043d"], "uncertainties": ["\u0424\u0438\u0437\u0438\u0447\u0435\u0441\u043a\u0438\u0439 LLM-\u043a\u04